const PptxGenJS = require('pptxgenjs');
const pres = new PptxGenJS();

pres.layout = 'LAYOUT_WIDE'; // 13.33 x 7.5 inches
pres.author = 'WorkspaceX';
pres.title = '团队协作：打造高效协同的力量';

// Color palette
const C = {
  primary: '1B4F72',    // deep blue
  accent: '2E86C1',     // medium blue
  light: 'D6EAF8',      // light blue bg
  white: 'FFFFFF',
  dark: '1C2833',       // near-black text
  gray: '5D6D7E',       // subtitle / secondary
  highlight: 'E67E22',  // orange accent
};

const FONT = '微软雅黑';

// ─── Helper functions ───
function addFooter(slide, pageNum) {
  slide.addText(`${pageNum} / 5`, {
    x: 12.0, y: 7.0, w: 1.0, h: 0.35,
    fontSize: 10, color: C.gray, fontFace: FONT, align: 'right'
  });
  // thin accent line at bottom
  slide.addShape(pres.ShapeType.rect, {
    x: 0, y: 7.35, w: 13.33, h: 0.15, fill: { color: C.primary }
  });
}

function addSectionTitle(slide, title, subtitle) {
  // left accent bar
  slide.addShape(pres.ShapeType.rect, {
    x: 0.5, y: 0.5, w: 0.12, h: 0.9, fill: { color: C.highlight }
  });
  slide.addText(title, {
    x: 0.85, y: 0.45, w: 11, h: 0.7,
    fontSize: 30, bold: true, color: C.primary, fontFace: FONT
  });
  if (subtitle) {
    slide.addText(subtitle, {
      x: 0.85, y: 1.15, w: 11, h: 0.45,
      fontSize: 16, color: C.gray, fontFace: FONT
    });
  }
}

// ════════════════════════════════════════
// SLIDE 1 — Cover
// ════════════════════════════════════════
const s1 = pres.addSlide();
s1.background = { fill: C.primary };

// decorative circle
s1.addShape(pres.ShapeType.ellipse, {
  x: 9.5, y: -1.5, w: 5.5, h: 5.5,
  fill: { color: C.accent, transparency: 60 }
});
s1.addShape(pres.ShapeType.ellipse, {
  x: -1.5, y: 4.5, w: 4, h: 4,
  fill: { color: C.accent, transparency: 70 }
});

s1.addText('团队协作', {
  x: 1.0, y: 2.0, w: 11, h: 1.5,
  fontSize: 52, bold: true, color: C.white, fontFace: FONT
});
s1.addText('打造高效协同的力量', {
  x: 1.0, y: 3.5, w: 11, h: 0.8,
  fontSize: 28, color: C.light, fontFace: FONT
});
s1.addText('2024 · 团队管理系列', {
  x: 1.0, y: 5.5, w: 6, h: 0.5,
  fontSize: 16, color: C.light, fontFace: FONT, italic: true
});

// ════════════════════════════════════════
// SLIDE 2 — Why Team Collaboration Matters
// ════════════════════════════════════════
const s2 = pres.addSlide();
s2.background = { fill: C.white };
addSectionTitle(s2, '为什么需要团队协作？', '从个体优秀到集体卓越的关键跨越');
addFooter(s2, 2);

const reasons = [
  { icon: '🎯', title: '目标对齐', desc: '统一方向，减少重复劳动\n让每个人的努力都指向同一目标' },
  { icon: '💡', title: '创新涌现', desc: '多元视角碰撞激发创意\n跨领域知识融合产生突破' },
  { icon: '⚡', title: '效率倍增', desc: '合理分工发挥各自优势\n协同作战远超单打独斗' },
  { icon: '🛡️', title: '风险共担', desc: '互相补位降低单点故障\n集体智慧提升决策质量' },
];

reasons.forEach((r, i) => {
  const col = i % 4;
  const xBase = 0.5 + col * 3.15;
  const yBase = 2.2;

  // card background
  s2.addShape(pres.ShapeType.roundRect, {
    x: xBase, y: yBase, w: 2.9, h: 4.2, rectRadius: 0.15,
    fill: { color: C.light }, shadow: { type: 'outer', blur: 6, offset: 2, color: 'AAAAAA', opacity: 0.3 }
  });
  // icon
  s2.addText(r.icon, {
    x: xBase, y: yBase + 0.3, w: 2.9, h: 0.8,
    fontSize: 40, align: 'center', fontFace: FONT
  });
  // card title
  s2.addText(r.title, {
    x: xBase + 0.2, y: yBase + 1.2, w: 2.5, h: 0.5,
    fontSize: 20, bold: true, color: C.primary, fontFace: FONT, align: 'center'
  });
  // card desc
  s2.addText(r.desc, {
    x: xBase + 0.2, y: yBase + 1.85, w: 2.5, h: 2.0,
    fontSize: 13, color: C.dark, fontFace: FONT, align: 'center', lineSpacingMultiple: 1.4
  });
});

// ════════════════════════════════════════
// SLIDE 3 — Core Principles
// ════════════════════════════════════════
const s3 = pres.addSlide();
s3.background = { fill: C.white };
addSectionTitle(s3, '高效协作的四大支柱', '构建可信赖的团队协作基础');
addFooter(s3, 3);

