  { num: '01', title: '透明沟通', items: ['信息主动共享，减少信息差', '反馈及时具体，对事不对人', '善用异步沟通，尊重专注时间'] },
  { num: '02', title: '明确权责', items: ['角色清晰，避免灰色地带', '决策权下放，减少审批瓶颈', 'RACI矩阵界定谁负责/审批'] },
